// Google Trends — STUB (02-API-KEYS-REQUIRED.md #1, two-path choice).
// Path (a) pytrends: unofficial Python lib, no key, but rate-limits. n8n Code nodes run
//   JS not Python, so pytrends CANNOT run here directly — it needs an external Python
//   microservice (FastAPI/Flask) that n8n calls via an HTTP Request node, OR run pytrends
//   in a scheduled container that POSTs into this workflow's webhook.
// Path (b) SerpAPI Google Trends endpoint: has a key (GOOGLE_TRENDS_SERPAPI_KEY), cleaner,
//   free 100 searches/mo. Swap this node for an HTTP Request node to
//   https://serpapi.com/search?engine=google_trends when Path (a) proves flaky (Priya rec:
//   start pytrends, upgrade to SerpAPI if it breaks).
// This stub emits ZERO items so the merge/tagger run cleanly on the other 3 sources until
// the Google-Trends path is wired. It NEVER fabricates trends (fail-closed, no garbage [A]).
// To activate Path (a): replace the return below with an HTTP call to your pytrends service:
//   const res = await this.helpers.httpRequest({ url: $env.PYTRENDS_SERVICE_URL, json: true });
//   return res.trends.map(t => ({ json: { raw: t.title, source: 'google_trends' } }));
return [];

// Normalize each source's raw payload into { text, source, category } BEFORE tagging.
// Pure shaping only — no keys, no external calls.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  // TMDb upcoming: { results: [ { title, release_date, ... } ] }
  if (Array.isArray(j.results)) {
    for (const m of j.results) {
      if (!m || !m.title) continue;
      out.push({ json: { text: String(m.title), source: 'tmdb', category: '', detected_extra: { release_date: m.release_date || null } } });
    }
    continue;
  }
  // NewsAPI: { articles: [ { title, ... } ] }
  if (Array.isArray(j.articles)) {
    for (const a of j.articles) {
      if (!a || !a.title) continue;
      out.push({ json: { text: String(a.title), source: 'news', category: 'entertainment' } });
    }
    continue;
  }
  // YouTube videos.list: { items: [ { snippet: { title } } ] }
  if (Array.isArray(j.items)) {
    for (const v of j.items) {
      const title = v && v.snippet && v.snippet.title;
      if (!title) continue;
      out.push({ json: { text: String(title), source: 'youtube_trending', category: '' } });
    }
    continue;
  }
  // Already-normalized (e.g. from the Google-Trends path): { raw, source }
  if (j.raw || j.text) {
    out.push({ json: { text: String(j.text || j.raw), source: j.source || 'google_trends', category: j.category || '' } });
  }
}
return out;

// ── Theme Tagger (INLINE copy of trendspark/n8n/theme-tagger.js — keep in sync) ──
// Verbatim closed vocab from Nisha's LOCKED config. NO secrets. Runs once per item.
const THEMES = new Set(['strength','action','energy','family','festive','light','tradition','pride','victory','beauty','glow','self-care','health','discipline','elegance','masculinity','femininity','power','celebration','joy','devotion','spirituality','luxury','comfort','wellness','fitness','confidence','style','glamour','radiance','purity','togetherness','heritage','authenticity','innovation','youth','vitality','calm','peace','resilience']);
const KEYWORD_TO_THEMES = {'action film':['action','strength','energy','power'],'sports film':['strength','victory','pride','discipline'],'romance':['beauty','joy','celebration','elegance'],'family drama':['family','togetherness','tradition','heritage'],'cricket':['pride','victory','energy','strength'],'football':['strength','energy','victory','pride'],'festival':['festive','celebration','joy','tradition'],'wedding':['celebration','family','tradition','joy'],'diwali':['festive','light','celebration','family','tradition'],'holi':['festive','celebration','joy','tradition'],'eid':['festive','family','tradition','celebration','devotion'],'navratri':['festive','celebration','tradition','spirituality','devotion'],'durga puja':['festive','celebration','tradition','spirituality','devotion'],'raksha bandhan':['family','togetherness','tradition','celebration'],'karva chauth':['tradition','devotion','celebration','family'],'bhai dooj':['family','togetherness','tradition','celebration'],'ganesh chaturthi':['festive','celebration','tradition','spirituality','devotion'],'onam':['festive','celebration','tradition','family'],'pongal':['festive','celebration','tradition','family'],'new year':['celebration','joy','energy','innovation'],'republic day':['pride','tradition','heritage','celebration'],'independence day':['pride','tradition','heritage','celebration'],'champions trophy':['pride','victory','energy','strength'],'world cup':['pride','victory','energy','strength'],'olympics':['strength','victory','pride','discipline'],'beauty':['beauty','glow','elegance','confidence'],'fitness':['strength','health','energy','discipline'],'yoga':['calm','peace','discipline','wellness'],'glow':['beauty','glow','radiance','confidence'],'skincare':['beauty','glow','self-care','radiance'],'workout':['strength','energy','discipline','fitness'],'gym':['strength','power','discipline','energy'],'traditional':['tradition','heritage','authenticity','elegance'],'ethnic':['tradition','heritage','elegance','celebration'],'bridal':['celebration','beauty','elegance','tradition'],'fashion week':['style','glamour','innovation','elegance'],'award show':['glamour','celebration','style','luxury']};
const NICHE_TO_THEMES = {fitness:['strength','health','energy','discipline','power','resilience','vitality'],supplement:['strength','health','energy','discipline','wellness','vitality'],apparel:['festive','tradition','elegance','style','confidence','heritage'],saree:['festive','tradition','elegance','femininity','heritage','celebration','beauty'],skincare:['beauty','glow','self-care','radiance','wellness','confidence','purity'],cosmetics:['beauty','glamour','confidence','style','radiance','elegance'],food:['tradition','celebration','family','joy','festive','heritage','authenticity'],jewelry:['luxury','elegance','celebration','tradition','beauty','glamour'],fashion:['style','elegance','confidence','innovation','youth','glamour'],sports:['strength','energy','victory','pride','power','discipline','resilience'],athleisure:['fitness','energy','style','confidence','comfort','youth'],wellness:['health','calm','peace','self-care','wellness','vitality'],yoga:['calm','peace','discipline','wellness','spirituality','vitality'],home:['comfort','family','togetherness','tradition','peace'],handloom:['heritage','tradition','authenticity','elegance','pride'],organic:['health','purity','authenticity','wellness','self-care'],luxury:['luxury','elegance','glamour','style','confidence'],entertainment:['style','glamour','celebration','joy'],health:['health','wellness','self-care','vitality']};
const CAMPAIGN_RULES = {PRIDE:{typical:1,keywords:['india win','cricket victory','world cup','champions trophy','olympics','medal','republic day','independence day','indian achievement','national pride','team india','victory','cricket']},SEASONAL:{typical:21,keywords:['diwali','holi','eid','navratri','durga puja','raksha bandhan','ganesh chaturthi','onam','pongal','new year','festival','celebration','sale','shopping season']},HYPE:{typical:3,keywords:['movie','film release','trailer launch','celeb launch','ott premiere','surprise','viral','trending now','award winner','film','trailer']},EDUCATIONAL:{typical:30,keywords:['health','fitness','wellness','yoga','nutrition','immunity','mental health','awareness','self-care','tips','how to','benefits of']}};
const matchesAny = (h, ks) => ks.some(k => h.includes(k));
function deriveCampaignType(t, sources, peak) {
  const src = (sources||[]).map(s => String(s).toLowerCase());
  const has = n => src.includes(n);
  if (matchesAny(t, CAMPAIGN_RULES.PRIDE.keywords)) return 'PRIDE';
  if (matchesAny(t, CAMPAIGN_RULES.EDUCATIONAL.keywords)) return 'EDUCATIONAL';
  if (has('tmdb') || matchesAny(t, CAMPAIGN_RULES.HYPE.keywords)) return 'HYPE';
  if (has('festival_calendar') || matchesAny(t, CAMPAIGN_RULES.SEASONAL.keywords)) return 'SEASONAL';
  if (typeof peak === 'number' && !Number.isNaN(peak)) { if (peak<=3) return 'HYPE'; if (peak<=7) return 'PRIDE'; return 'SEASONAL'; }
  return 'EDUCATIONAL';
}
function tagTrend(raw) {
  const text = String((raw&&raw.text)||'').trim();
  const lowered = text.toLowerCase();
  const sources = Array.isArray(raw&&raw.source) ? raw.source : (raw&&raw.source ? [raw.source] : []);
  const category = String((raw&&raw.category)||'').trim().toLowerCase();
  const collected = new Set();
  for (const [k, th] of Object.entries(KEYWORD_TO_THEMES)) { if (lowered.includes(k)) th.forEach(x => collected.add(x)); }
  if (category && NICHE_TO_THEMES[category]) NICHE_TO_THEMES[category].forEach(x => collected.add(x));
  const themes = [...collected].filter(x => THEMES.has(x));
  const campaign_type = deriveCampaignType(lowered, sources, raw&&raw.peakWindowDays);
  const peak_window_days = (typeof (raw&&raw.peakWindowDays)==='number' && !Number.isNaN(raw.peakWindowDays)) ? raw.peakWindowDays : CAMPAIGN_RULES[campaign_type].typical;
  return { trend_text: text, source: sources.map(s => String(s).toLowerCase()), themes, campaign_type, peak_window_days };
}
// ── ULID (Crockford base32, no deps) ──
function ulid() {
  const ENC = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  let ts = Date.now(), tp = '';
  for (let i = 9; i >= 0; i--) { tp = ENC[ts % 32] + tp; ts = Math.floor(ts / 32); }
  let rp = '';
  for (let i = 0; i < 16; i++) rp += ENC[Math.floor(Math.random() * 32)];
  return tp + rp;
}
function pad(n){ return String(n).padStart(2,'0'); }
function fmtDate(d){ return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; }
function fmtDateTime(d){ return `${fmtDate(d)} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}.000000`; }

const now = new Date();
const detected = fmtDate(now);
const out = [];
for (const item of $input.all()) {
  const tagged = tagTrend(item.json || {});
  // Fail-closed: drop empty text OR no themes matched — never write garbage rows [03-PIPELINE-CHAIN A].
  if (!tagged.trend_text || tagged.themes.length === 0) continue;
  const expires = new Date(now.getTime() + tagged.peak_window_days * 24 * 60 * 60 * 1000);
  out.push({ json: {
    id: ulid(),
    trend_text: tagged.trend_text.slice(0, 500),
    source: JSON.stringify(tagged.source),
    region: 'IN',
    detected_date: detected,
    peak_window_days: tagged.peak_window_days,
    expires_at: fmtDateTime(expires),
    themes: JSON.stringify(tagged.themes),
    campaign_type: tagged.campaign_type,
    created_at: fmtDateTime(now),
    updated_at: fmtDateTime(now)
  }});
}
return out;
